import com.luci.pianoroom.*;import java.util.*;
public class ProtocolAndBufferTest{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static byte[] bytes(String s){String[] p=s.split(" ");byte[] b=new byte[p.length];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(p[i],16);return b;}
 public static void main(String[] args){
  byte[] expected=bytes("F0 43 73 01 52 25 26 01 01 0C 00 00 01 00 01 00 00 01 20 F7");
  check(Arrays.equals(expected,YamahaProtocol.set(YamahaProtocol.VOLUME,0,new byte[]{32})),"native volume packet");
  byte[] info=bytes("F0 43 73 01 52 25 26 00 00 0C 00 00 01 00 01 00 00 01 64 F7");
  byte[] ack=bytes("F0 43 73 01 52 25 26 00 01 0C 00 00 01 00 01 00 00 00 00 01 20 F7");
  check(YamahaProtocol.reply(info).data[0]==100,"read response");check(YamahaProtocol.reply(ack).ack,"write acknowledgement");check(YamahaProtocol.reply(expected)==null,"ignore outbound echo");
  byte[] corrupt=info.clone();corrupt[17]=2;check(YamahaProtocol.reply(corrupt)==null,"reject truncated body");corrupt=info.clone();corrupt[3]=2;check(YamahaProtocol.reply(corrupt)==null,"reject unrelated header");
  List<byte[]> messages=new ArrayList<>();YamahaRemote remote=new YamahaRemote(b->{messages.add(b.clone());return true;},()->{});remote.probe();int before=messages.size();remote.volume(0);check(messages.size()==before,"no writes before read confirmation");remote.receive(info);check(remote.ready(),"read unlocks supported parameter");remote.volume(32);check(remote.waiting()&&remote.confirmed==0,"sending is not confirmation");remote.receive(ack);check(!remote.waiting()&&remote.confirmed==1,"matching reply confirms value");remote.restore();boolean original=false;for(byte[] b:messages)if(Arrays.equals(b,YamahaProtocol.set(YamahaProtocol.VOLUME,0,new byte[]{100})))original=true;check(original,"restore original value, not 127");
  remote.reset();remote.probe();byte[] muted=info.clone();muted[18]=0;remote.receive(muted);int recoveryStart=messages.size();remote.restore();check(messages.size()==recoveryStart,"automatic restore retains original zero");remote.restore(true);check(messages.size()>recoveryStart&&remote.waiting(),"explicit recovery sends audible volume and waits for confirmation");check(Arrays.equals(messages.get(recoveryStart),YamahaProtocol.set(YamahaProtocol.VOLUME,0,new byte[]{100})),"recover reconnected muted piano");remote.receive(info);check(!remote.waiting()&&remote.number(YamahaProtocol.VOLUME,0,-1)==100,"recovery acknowledged by piano");
  List<byte[]> sx=new ArrayList<>();List<Integer> notes=new ArrayList<>();MidiParser parser=new MidiParser((s,a,b)->notes.add(a),sx::add);byte[] begin=Arrays.copyOfRange(info,0,9);parser.accept(begin,0,begin.length);parser.accept(new byte[]{(byte)0xF8},0,1);byte[] end=Arrays.copyOfRange(info,9,info.length);parser.accept(end,0,end.length);parser.accept(new byte[]{(byte)0x90,60,100},0,3);check(sx.size()==1&&Arrays.equals(sx.get(0),info)&&notes.size()==1,"fragmented SysEx plus realtime and note");byte[] overflow=new byte[5000];overflow[0]=(byte)0xF0;overflow[4999]=(byte)0xF7;parser.accept(overflow,0,overflow.length);check(sx.size()==1,"bounded SysEx");parser.accept(info,0,info.length);check(sx.size()==2,"resync after oversized SysEx");
  byte[] model=bytes("F0 43 73 01 52 25 26 00 00 0F 01 18 01 00 01 00 00 08 00 50 2D 31 34 35 42 54 F7");check(YamahaProtocol.text(YamahaProtocol.reply(model).data).equals("P-145BT"),"decode real P-145BT diagnostic response without duplicate length");
  remote.reset();remote.probe();remote.receive(model);check(remote.model.equals("P-145BT")&&!remote.ready(),"model identification does not imply volume support");
  AudioBufferPolicy policy=new AudioBufferPolicy();policy.configure(0,32,true,AudioBufferPolicy.framesForMs(200));check(AudioBufferPolicy.millis(policy.frames())>=32,"safe initial buffer");policy.observe(837,1);int initial=policy.frames();check(!policy.observe(837,500000002L)&&policy.frames()==initial,"old historical underruns alone do not enlarge buffer");check(policy.observe(841,1000000003L)&&policy.frames()>initial,"new repeated underruns increase buffer beyond old 16ms ceiling");for(int i=1;i<30;i++)policy.observe(841+i*5,1000000003L+i*500000001L);check(policy.frames()==AudioBufferPolicy.framesForMs(120),"automatic adjustment bounded at 120ms");
  policy.configure(2,16,false,8820);policy.observe(0,1);check(!policy.observe(99,500000002L)&&policy.frames()==AudioBufferPolicy.framesForMs(16),"manual fixed buffer stays fixed");policy.configure(1,32,true,1024);policy.observe(0,1);for(int i=1;i<20;i++)policy.observe(i*5,1+i*500000001L);check(policy.frames()<=1024,"respect actual driver capacity");check(AudioBufferPolicy.queued(100,110)==0,"safe counter difference");
  System.out.println("PASS: SysEx parsing, read-before-write, confirmation/restoration, fragmented messages, real P-145BT model response, historical vs new underruns, adaptive/manual buffer and capacity bounds.");
 }
}
